import datetime
from cryptography.hazmat.primitives.asymmetric import ed25519

def _today_bytes() -> bytes:
    # Returns YYYY-MM-DD as bytes; can be monkey‑patched in tests.
    return datetime.date.today().isoformat().encode()

def sign_with_timestamp(data: bytes, key: bytes) -> bytes:
    """Sign `data` concatenated with today's date (YYYY‑MM‑DD) using Ed25519."""
    signer = ed25519.Ed25519PrivateKey.from_private_bytes(key)
    return signer.sign(data + _today_bytes())
