import time
import psutil
from datetime import datetime

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    while True:
        now = datetime.utcnow().isoformat()
        for c in psutil.net_connections(kind='tcp'):
            if c.laddr.ip == host and c.status == 'ESTABLISHED' and c.raddr:
                logs.append({
                    "timestamp": now,
                    "source_ip": c.raddr.ip,
                    "source_port": c.raddr.port
                })
        time.sleep(interval_s)
        # break condition can be added as needed
    return logs
