import hashlib
from copy import deepcopy

def _hash_value(val: str) -> str:
    return hashlib.sha256(val.encode('utf-8')).hexdigest()

def anonymize_dataset(records: list[dict], fields: list[str]) -> list[dict]:
    """Return a copy of *records* with the given *fields* anonymized."""
    anon = []
    for rec in records:
        new_rec = deepcopy(rec)
        for f in fields:
            if f in new_rec and isinstance(new_rec[f], str):
                new_rec[f] = _hash_value(new_rec[f])
        anon.append(new_rec)
    return anon
```

